-- ════════════ 0004_projector_stages.sql ════════════
-- Projector upgrade: a fundraising goal and two extra host-selectable screens (Welcome, Thank you).
-- ADDITIVE ONLY.
alter table events add column goal_cents integer check (goal_cents is null or goal_cents > 0);
alter table events drop constraint events_display_mode_check;
alter table events add constraint events_display_mode_check
  check (display_mode in ('auto', 'dashboard', 'live', 'message', 'welcome', 'thanks'));

insert into schema_migrations (name) values ('0004_projector_stages.sql') on conflict do nothing;

-- ════════════ 0005_pie_brandon.sql ════════════
-- "Pie Brandon in the Face": sign-ups sold at the Bid Desk all night (small $100 / large $200), thrown at the finale.
-- ADDITIVE ONLY. Sold through the same desk records as Power-Ups, but kept in their own ledger line.
alter table powerup_defs add column category text not null default 'powerup' check (category in ('powerup', 'pie'));

insert into powerup_defs (code, name, description, icon, price_cents, enabled, kinds, max_per_bidder_item, max_per_item, max_per_bidder, config, sort, category) values
 ('pie_small', 'Pie Brandon in the Face — Small', 'Sign up to throw a small pie at Brandon''s face at the end of the night.', 'cake', 10000, true, '{}', null, null, null, '{}', 20, 'pie'),
 ('pie_large', 'Pie Brandon in the Face — Large', 'Sign up to throw a LARGE pie at Brandon''s face at the end of the night.', 'cake', 20000, true, '{}', null, null, null, '{}', 21, 'pie');

-- One row per pie actually thrown at the finale (append-only). Each consumes one unit of the guest's sign-ups.
create table pie_throws (
  id                   uuid primary key default gen_random_uuid(),
  event_id             uuid not null references events(id),
  bidder_id            uuid not null references bidders(id),
  powerup_code         text not null references powerup_defs(code),
  thrown_by_admin_id   uuid not null references admin_users(id),
  created_at           timestamptz not null default now()
);
create index pie_throws_bidder_idx on pie_throws (bidder_id, powerup_code);
create trigger pie_throws_immutable before update or delete on pie_throws
  for each row execute function forbid_mutation();
alter table pie_throws enable row level security;

-- Host-selectable projector screen for the finale.
alter table events drop constraint events_display_mode_check;
alter table events add constraint events_display_mode_check
  check (display_mode in ('auto', 'dashboard', 'live', 'message', 'welcome', 'thanks', 'pie'));

insert into schema_migrations (name) values ('0005_pie_brandon.sql') on conflict do nothing;

-- ════════════ 0006_online_payments.sql ════════════
-- Online card payments (Square). ADDITIVE; off by default (events.online_payments = false).
alter table events add column online_payments boolean not null default false;

-- An online payment has no volunteer who "received" it, and has its own method.
alter table payments alter column received_by_admin_id drop not null;
alter table payments drop constraint payments_method_check;
alter table payments add constraint payments_method_check check (method in ('cash', 'check', 'card_terminal', 'online_card'));

-- One row per "Pay now" tap. Money is only applied to a balance when Square confirms it was really paid.
create table online_payments (
  id                 uuid primary key default gen_random_uuid(),
  event_id           uuid not null references events(id),
  bidder_id          uuid not null references bidders(id),
  amount_cents       integer not null check (amount_cents > 0),          -- what the guest was asked to pay
  status             text not null default 'created' check (status in ('created', 'paid', 'paid_refund_due', 'failed')),
  square_link_id     text,
  square_order_id    text unique,
  square_payment_id  text unique,
  applied_cents      integer not null default 0,                         -- how much actually went onto their balance
  refund_due_cents   integer not null default 0,                         -- paid more than they owed by then (refund in Square)
  created_at         timestamptz not null default now(),
  paid_at            timestamptz
);
create index online_payments_bidder_idx on online_payments (bidder_id, created_at desc);
alter table online_payments enable row level security;

insert into schema_migrations (name) values ('0006_online_payments.sql') on conflict do nothing;

-- ════════════ 0007_merge_challenge_into_resurrection.sql ════════════
-- The Challenge Flag is folded into Resurrection: one reopening per item, optionally with the guest's own bid.
-- Resurrection is for live items only (silent items never have a last-chance window). The Flag is switched off, not deleted,
-- so any already-recorded purchases/uses keep their history.
update powerup_defs
   set kinds = '{live}',
       description = 'Bring a just-ended live auction back for 60 seconds, once per item. Add your own bid to take the lead — or reopen it and let everyone bid.'
 where code = 'resurrection';

update powerup_defs set enabled = false where code = 'challenge_flag';

insert into schema_migrations (name) values ('0007_merge_challenge_into_resurrection.sql') on conflict do nothing;

-- ════════════ 0008_commercial_breaks.sql ════════════
-- Commercial breaks: the host plays a short video takeover on the projector, optionally promoting one silent item.
-- ADDITIVE. The clip list itself lives in code (src/lib/commercials.ts); the event only remembers which one is playing.
alter table events
  add column commercial_key        text,
  add column commercial_item_id    uuid references auction_items(id) on delete set null,
  add column commercial_started_at timestamptz;

insert into schema_migrations (name) values ('0008_commercial_breaks.sql') on conflict do nothing;

-- ════════════ 0009_commercial_before_live_item.sql ════════════
-- A commercial can play right before a live item opens for bidding: the host taps Start, the commercial plays, and the item
-- opens the moment it ends (or when the host skips it). These two columns hold that pending start. ADDITIVE.
alter table events
  add column commercial_start_item_id uuid references auction_items(id) on delete set null,
  add column commercial_admin_id      uuid references admin_users(id) on delete set null;

insert into schema_migrations (name) values ('0009_commercial_before_live_item.sql') on conflict do nothing;

